var t=[{title:`Begin met het doel`,text:`Elke beweging heeft een taak: een squat traint heup- en kniestrekking samen, een row traint trekken en een hinge werkt vooral via de heupen. Goede techniek kan er van persoon tot persoon een beetje anders uitzien omdat beenlengte, mobiliteit en uitrusting verschillen. Wat telt is veilige, herhaalbare controle. Niemand hoeft één exacte look na te bootsen.`},{title:`Bouw het fundament`,text:`Leer eerst een versie zonder of met licht gewicht. Gebruik een bewegingsbereik dat je kunt beheersen, vloeiende herhalingen en stabiele steun wanneer je die nodig hebt. Bouw dan in kleine stappen op: meer herhalingen, meer weerstand of een complexere versie. Jezelf filmen of met een gekwalificeerde coach werken kan gewoonten zichtbaar maken, maar video alleen kan geen blessure vaststellen.`},{title:`Wanneer de vorm afbrokkelt`,text:`Waarschuwingssignalen binnen een set zijn onder andere je evenwicht verliezen, het gewicht onbeheerst laten zakken, van het bedoelde pad afwijken of compensaties die erger worden naarmate je moe wordt. Stop of maak de oefening makkelijker als je ze ziet. Zwaarder tillen met instortende techniek is geen vooruitgang.`},{title:`Voorbeeld`,text:`Oefen voordat je een dumbbell Romanian deadlift belast het heupscharnier met je handen op je heupen en daarna met een licht gewicht. Voeg pas gewicht toe als je heupen beheerst naar achteren gaan en je rugpositie van herhaling tot herhaling hetzelfde blijft voor jouw lichaam.`},{title:`TrainUp gebruiken`,text:`Je schema kiest oefeningen die passen bij je niveau en coördinatie, en elke oefeningpagina bij Oefeningen heeft stappen en techniekaanwijzingen. TrainUp schrijft geen gewichten voor, dus jij kiest het gewicht. Leg je herhalingen vast tijdens de training en beoordeel daarna je inspanning, en voeg gewicht toe in kleine stappen zonder elke training een record na te jagen.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Praktische richtlijnen van het ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};